package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.bus.*;import vn.edu.eaut.lab5.model.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.io.*;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.time.LocalDate;import java.util.List;
public class HoaDonPanel extends JPanel {private final KhachHangBUS khBus=new KhachHangBUS();private final SanPhamBUS spBus=new SanPhamBUS();private final HoaDonBUS hdBus=new HoaDonBUS();private final JComboBox<KhachHang> customers=new JComboBox<>();private final JComboBox<SanPham> products=new JComboBox<>();private final JTextField quantity=new JTextField();private final JLabel total=new JLabel("Tong tien: 0 VND"),stock=new JLabel();private final JButton add=new JButton("Them vao hoa don"),remove=new JButton("Xoa dong"),save=new JButton("Luu hoa don"),clear=new JButton("Lam moi"),export=new JButton("Xuat hoa don");private final DefaultTableModel model=new DefaultTableModel(new Object[]{"Ma SP","Ten san pham","So luong","Don gia","Thanh tien"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private HoaDon last;
 public HoaDonPanel(){this(true);}public HoaDonPanel(boolean canCreate){setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(10,10,10,10));JPanel f=new JPanel(new GridLayout(2,4,8,8));f.add(new JLabel("Khach hang:"));f.add(customers);f.add(new JLabel("San pham:"));f.add(products);f.add(new JLabel("So luong:"));f.add(quantity);f.add(stock);f.add(add);JPanel a=new JPanel(new FlowLayout(FlowLayout.LEFT));for(JButton b:new JButton[]{remove,save,clear,export})a.add(b);JPanel top=new JPanel(new BorderLayout(5,5));top.add(f,BorderLayout.NORTH);top.add(a,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);add(total,BorderLayout.SOUTH);export.setEnabled(false);add.addActionListener(e->addLine());remove.addActionListener(e->removeLine());save.addActionListener(e->saveInvoice());clear.addActionListener(e->reset());export.addActionListener(e->exportTxt());products.addActionListener(e->showStock());if(!canCreate){add.setEnabled(false);remove.setEnabled(false);save.setEnabled(false);clear.setEnabled(false);quantity.setEnabled(false);customers.setEnabled(false);products.setEnabled(false);}loadChoices();}
 private void loadChoices(){new SwingWorker<Object[],Void>(){protected Object[] doInBackground()throws Exception{return new Object[]{khBus.findAll(),spBus.findAll()};}protected void done(){try{Object[] a=get();for(KhachHang x:(List<KhachHang>)a[0])customers.addItem(x);for(SanPham x:(List<SanPham>)a[1])products.addItem(x);}catch(Exception e){error("Khong the tai du lieu",e);}}}.execute();}private void showStock(){SanPham x=(SanPham)products.getSelectedItem();stock.setText(x==null?"":"Ton kho: "+x.getSoLuong()+(x.getSoLuong()<5?" - SAP HET":""));}
 private void addLine(){try{SanPham x=(SanPham)products.getSelectedItem();if(x==null)throw new IllegalArgumentException("Phai chon san pham");int q=Integer.parseInt(quantity.getText().trim());if(q<=0)throw new IllegalArgumentException("So luong phai lon hon 0");for(int i=0;i<model.getRowCount();i++)if((int)model.getValueAt(i,0)==x.getMaSp()){int n=(int)model.getValueAt(i,2)+q;if(n>x.getSoLuong())throw new IllegalArgumentException("Vuot qua ton kho");model.setValueAt(n,i,2);model.setValueAt(x.getDonGia().multiply(BigDecimal.valueOf(n)),i,4);updateTotal();return;}if(q>x.getSoLuong())throw new IllegalArgumentException("Vuot qua ton kho");model.addRow(new Object[]{x.getMaSp(),x.getTenSp(),q,x.getDonGia(),x.getDonGia().multiply(BigDecimal.valueOf(q))});updateTotal();quantity.setText("");}catch(Exception e){error("Khong the them san pham",e);}}
 private void removeLine(){int r=table.getSelectedRow();if(r>=0){model.removeRow(r);updateTotal();}}private void updateTotal(){BigDecimal v=BigDecimal.ZERO;for(int i=0;i<model.getRowCount();i++)v=v.add((BigDecimal)model.getValueAt(i,4));total.setText("Tong tien: "+v+" VND");}
 private void saveInvoice(){try{KhachHang k=(KhachHang)customers.getSelectedItem();if(k==null)throw new IllegalArgumentException("Phai chon khach hang");if(model.getRowCount()==0)throw new IllegalArgumentException("Hoa don phai co chi tiet");HoaDon h=new HoaDon();h.setMaKh(k.getMaKh());h.setTenKh(k.getTenKh());h.setSdtKh(k.getSdt());h.setNgayLap(LocalDate.now());for(int i=0;i<model.getRowCount();i++)h.getChiTiet().add(new ChiTietHoaDon((int)model.getValueAt(i,0),(String)model.getValueAt(i,1),(int)model.getValueAt(i,2),(BigDecimal)model.getValueAt(i,3)));int id=hdBus.save(h);last=h;export.setEnabled(true);JOptionPane.showMessageDialog(this,"Luu thanh cong. Ma hoa don: "+id);model.setRowCount(0);updateTotal();}catch(Exception e){error("Khong the luu hoa don",e);}}
 private void reset(){model.setRowCount(0);updateTotal();last=null;export.setEnabled(false);quantity.setText("");}private void exportTxt(){if(last==null)return;JFileChooser fc=new JFileChooser();fc.setSelectedFile(new File("HoaDon_"+last.getMaHd()+".txt"));if(fc.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(Writer w=new OutputStreamWriter(new FileOutputStream(fc.getSelectedFile()),StandardCharsets.UTF_8)){w.write("MINISHOP\nMa hoa don: "+last.getMaHd()+"\nNgay lap: "+last.getNgayLap()+"\nKhach hang: "+last.getTenKh()+"\nSo dien thoai: "+last.getSdtKh()+"\n\nDanh sach:\n");for(ChiTietHoaDon x:last.getChiTiet())w.write(x.getTenSp()+" | "+x.getSoLuong()+" | "+x.getDonGia()+" | "+x.getThanhTien()+"\n");w.write("\nTong tien: "+last.getTongTien()+" VND\n");JOptionPane.showMessageDialog(this,"Da xuat file");}catch(IOException e){error("Khong the xuat file",e);}}private void error(String t,Exception e){Throwable x=e.getCause()==null?e:e.getCause();JOptionPane.showMessageDialog(this,t+": "+x.getMessage(),"Loi",JOptionPane.ERROR_MESSAGE);}}
